/// <summary>
/// class <c>METTelemetrySOReservationErrorEvent</c> is used to log error event whenever sales order is reserved.
/// </summary>
internal final class METTelemetrySOReservationErrorEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetrySOReservationErrorEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetrySOReservationErrorEvent</c> </returns>
public static METTelemetrySOReservationErrorEvent construct()
{
    return new METTelemetrySOReservationErrorEvent();
}

/// <summary>
/// Run confirmation journal error event 
/// </summary>
/// <param name = "_salesID"> Sales id </param>
/// <param name = "_error"> error message </param>
public static void runTelemetryEvent(SalesId _salesID, str _error)
{
    METTelemetrySOReservationErrorEvent reservedErrorEvent = METTelemetrySOReservationErrorEvent::construct();

    reservedErrorEvent.addRunTimePropertyToAppinsights(_salesID, _error);

    reservedErrorEvent.processEvent(METTelemetryEventNames::SOReserveErrorEvent);
}

/// <summary>
/// Initializes the parameter setup values.
/// </summary>
/// <param name = "_parameterSetup">The parameter setup record to initialize.</param>
protected void initializeParameterSetup(ISMTelemetryParameterSetup _parameterSetup)
{
    _parameterSetup.TelemetryClass = this.telemetryName();
    _parameterSetup.IsEnabled = NoYes::Yes;
    _parameterSetup.SeverityLevel = ISMTelemetrySeverityLevel::Error;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_salesID"> SalesID </c> </param>
public void addRunTimePropertyToAppinsights(SalesID _SalesId, str _error)
{
    SalesTable salesTable = SalesTable::find(_SalesId);
    METSalesTable metSalestable = METSalesTable::findBySalesTable(salesTable.RecId);

    this.addRuntimeProperty('salesOrderNumber', salesTable.SalesId);
    this.addRuntimeProperty('warehouseId' ,salesTable.InventLocationId);
    this.addRuntimeProperty('orderReferenceNumber', salesTable.CustomerRef);
    this.addRuntimeProperty('industryKey', metSalestable.IndustryKey);
    this.addRuntimeProperty('metcashSalesOrderType', salesTable.METSalesOrderType);
    this.addRuntimeProperty('customerNumber', salesTable.CustAccount);
    this.addRuntimeProperty('transmissionNumber', metSalestable.TransmissionNumber); 
    this.addRuntimeProperty('Message', _error);
}

/// <summary>
/// Add the error oiinfo when reservation is failed
/// </summary>
/// <param name = "_inventTrans"> Instance of table <c>InventTrans</c>/param>
/// <param name = "_error"> Error message</param>
public static void reservationFailed(InventTrans _inventTrans)
{
    InventTransOrigin transOrigin = InventTransOrigin::find(_inventTrans.inventTransOrigin) ;

    SalesLine salesLine = SalesLine::findInventTransId(transOrigin.InventTransId);

    if (salesLine.SalesId)
    {
        METTelemetrySOReservationErrorEvent::runTelemetryEvent(salesLine.SalesId, "@SCM:AutomaticReservationFailed");
    }
}
